                    “也不知道老师什么时候回来…”坐在莲旁边的长生面色略显不安，不知道是因为被莲数落了一番还是有其他的原因。
                    “呼！你小子还怕这妞逃脱了不成！？等会我把她弄晕了换个绑法！给你好好爽爽！”薛宝的腰不停地发力，没有间歇地冲击着白枫的口腔。
                    “嗯呜！呜噢噢！！”由于动作过于激烈，铁椅子与地面发出强烈的摩擦声响彻整个空间，在这吵杂的声音下，插在白枫后庭与蜜穴内的两根东西所发出的声音反而不那么清晰了，白枫半空中的双峰不停摇晃着，犹如快要坠落的水滴一般。
                    “…这货还真是简单易懂呢。”莲的眼神中透出一股寒光，瞥向正在办事的薛宝和白枫。
