                    “呕咳咳！！啊咔嗷！！”薛宝储存的弹药数量确实多得惊人，在身体松弛下来后，他便粗鲁地将炮筒从白枫的嘴里抽了出来，就在巨物与白枫的嘴分离的那一瞬间，白色的洪流就好像决堤一般从白枫的嘴里倾泻出来，并向地面喷去，犹如一条急流的白色瀑布。
                    “如何啊，这天生的神力可是学不来的！”薛宝拿起一块毛巾，擦拭着那条刚从白枫嘴里拔出来的炮筒。
                    “咔呜！呜呋！噢呜！”擦拭完后，薛宝便扯着白枫的头发，然后将那块毛巾一股脑儿塞进了她的嘴里，然后又用银色的胶带绕着她的脸围了好几圈，防止白枫将毛巾从嘴里吐出。
                    “呕！好臭…！混…蛋！！”腥臭味充斥着白枫的口腔，前所未有的屈辱感令白枫羞愤难耐，她愤恨地瞪着薛宝，心里恐怕早已把这家伙碎尸万段了。
                    “宝哥…差不多了吧…万一真出什么事，老师那里也不好交代…”看着白枫痛苦的表情，长生提醒道，生怕薛宝没有节制地搞下去会出事。
