                    另一方面，白枫的mini停靠在路边。
                    
                    “交货的地点居然是‘小极缘’？”驾驶室内的刑渊看着眼前的街道说道。街道的内部充斥着各种花色的霓虹灯，酒醉的男人们搂着那些穿着暴露的女人们，醉后的人们丑态毕露，他们大声嚷嚷，宣泄着日常的情绪，然后各自游走在这条满是粉红蒸汽的街道上。而这条街道的入口处，则矗立着一块犹如神社一般的红色架子，架子的正中间是被霓虹灯光的光晕环绕着的三个大字，小极缘。
                    “怎么会选小极缘交易…？买家是…詹姆斯·谭，啊…这货是人类经销商啊？专门消化鸟笼业务的下游商人，难怪了…之前太过紧张都没有仔细看过这个委托的详细情报呢，光想着抓人了…”刑渊的手机上阐述了详细的委托情报，当然也包括委托人的资料，都快到交货地点才开始审查资料确实不是刑渊的作风，白枫被绑架的事，确实令他有些失常。
                    “车子开不进去的，只能靠走么…嘁！小极缘可是人雀最不喜欢的地方呢…这里到处都是好吃懒做的‘人鸠’啊…”所谓的人鸠，指的是专门截胡人雀肉货的强盗，在截胡了人雀的肉货后，由于没有买家信息，所以人鸠便将肉货卖给红灯区的商家进行调教，进而赚取可观的利润，为了买卖方便，大多数人鸠都会选择在红灯区常驻，一来可以与商家保持密切的联系，二来也可以获得一些有价值的情报，这第三嘛，很多商家在人力不足的情况下，依旧会在淘气包上发布委托，依靠鸟笼强大的系统和人力来扩充店里的女人数量，和那些单个的买家不同，红灯区是鸟笼的主要消化渠道，也就是所谓的大客户，所以人雀在这里的出现频率相当地高，因此清楚这一点的人鸠，必然会选择在这种地方对人雀进行狙击。
                    而小极缘，则是目前最大，也是最火热的红灯区。
                    
