                    “抱歉，这是詹姆斯·谭先生的货物，有需要的话请去他名下的店里咨询哦！”刑渊挡住男人那只想要轻薄暮百花的咸猪手并解释道。
                    “啊？你是来送货的人雀么？嘿嘿…胆子真大啊！既然是大詹的东西，我也不想找麻烦，之后我再去打听你被送去哪家店调教了哦，美人！”男人比了个飞吻后便不再继续纠缠。
