                    “不远了…这样招摇的话，人鸠应该也很难下手，毕竟如果被知道是谁干的话，鸟笼也不会坐视不理！”
                    
                    “寂皇…我已经快到交货地点了，完成委托后你一定要遵守约定！”滴滴滴，此时，寂皇预留给刑渊的手机响了起来，刑渊迫不及待且得意忘形地对着话筒说道。
