                    不久后，刑渊按照淘气包的导航逐渐接近交货地点。
                    “怎么越来越偏僻了…？小极缘的内部原来这么大的么…？”周围的人群越来越少，熙攘的粉红色蒸汽也逐渐远去，小极缘的深处是寂静清冷，人迹罕至的街道，和之前的热闹不同，这里好像还没有被开发过一样，到处都是冷清的地块和尚未建成的矮屋。
